def compute_order_flow_imbalance(bids, asks, window=20):
    # 计算多空挂单瞬态失衡度 OFI
    delta_bid = bids[:, 0] - np.roll(bids[:, 0], 1)
    delta_ask = asks[:, 0] - np.roll(asks[:, 0], 1)
    ofi = np.where(delta_bid > 0, bids[:, 1], 0) - np.where(delta_ask < 0, asks[:, 1], 0)
    return pd.Series(ofi).rolling(window).mean()
